/* Source workbook mapping. Imported teaching answers never execute as medication rules. */
(function(root){
const bool=v=>v==='Yes'?true:v==='No'?false:null;
const number=v=>typeof v==='number'&&Number.isFinite(v)?v:null;
function normalized(r){const scenario=!!r.Scenario;return {age:number(r['Age (years)']),sbp:number(r['Systolic BP (mmHg)']),burden:r['Burden of illness']||'Unknown',copd:bool(r.COPD),priorFungal:bool(r['Previous fungal infection']),category:r['Cancer category']==='Solid tumour'?'Solid tumour':['Lymphoma','Leukaemia','Multiple myeloma'].includes(r['Cancer category'])?'Haematological':'Unknown',dehydration:bool(r['Dehydration needing IV fluids']),setting:r['Setting at fever onset']||'Unknown',mucositis:bool(r['Mucositis grade 3–4']),pneumonia:bool(r['Pneumonia / complex infection']),lineInfection:bool(r[scenario?'Catheter / skin–soft-tissue infection':'Catheter infection']),prolonged:bool(r['Expected ANC <0.1 for ≥7 days']),liver:bool(r['AST/ALT >5× ULN']),confusion:bool(r['New confusion / neuro change']),sepsis:scenario?bool(r['Sepsis: haemodynamic instability or organ dysfunction']):null,crcl:number(r['CrCl (mL/min)'])};}
function mascc(p,c){const parts=[],missing=[];function add(name,valid,points){parts.push({name,points:valid?points:null});if(!valid)missing.push(name)}add('Symptom burden',Object.hasOwn(c.burden,p.burden),c.burden[p.burden]);add('Systolic BP',p.sbp!==null,p.sbp>c.hypotensionThreshold?c.noHypotension:0);add('No COPD',p.copd!==null,p.copd===false?c.noCOPD:0);add('Cancer / previous fungal infection',p.category==='Solid tumour'||p.category==='Haematological'&&p.priorFungal!==null,p.category==='Solid tumour'||p.priorFungal===false?c.cancerFungal:0);add('No dehydration',p.dehydration!==null,p.dehydration===false?c.noDehydration:0);add('Outpatient at fever onset',['Outpatient','Inpatient'].includes(p.setting),p.setting==='Outpatient'?c.outpatient:0);add('Age below cutoff',p.age!==null,p.age<c.ageCutoff?c.age:0);return {score:missing.length?null:parts.reduce((s,x)=>s+x.points,0),parts,missing};}
function assessment(r,c){const p=normalized(r),m=mascc(p,c),flags=[];for(const [key,label]of [['mucositis','Severe mucositis'],['pneumonia','Complex infection / pneumonia'],['lineInfection','Line / skin infection'],['prolonged','Prolonged profound neutropenia'],['liver','Liver dysfunction'],['confusion','New confusion'],['sepsis','Sepsis / organ dysfunction']])if(p[key]===true)flags.push(label);if(p.setting==='Inpatient')flags.push('Inpatient at onset (workbook rule)');if(p.crcl!==null&&p.crcl<30)flags.push('CrCl <30 mL/min (workbook rule)');const unstable=p.sepsis===true||p.sbp!==null&&p.sbp<=c.hypotensionThreshold;if(unstable)flags.push('Urgent instability review');const risk=flags.length?'High':m.score===null?'Unknown':m.score<c.lowThreshold?'High':'Low';return {...m,risk,flags,unstable,renal:p.crcl!==null&&p.crcl<30,allergy:r['Penicillin allergy']&&r['Penicillin allergy']!=='None'?r['Penicillin allergy']:null};}
function prefill(r,blank){const p={...blank,...normalized(r)};if(p.liver===true||p.sepsis===true)p.majorComorbidity=true;delete p.liver;delete p.sepsis;p.cancer=r.Diagnosis||'';p.sex=r.Sex||'Unknown';p.chemoDay=number(r['Days since last chemo']);p.temp=number(r['Temp (°C)']);p.anc=number(r['ANC (×10⁹/L)']);p.hr=number(r['Heart rate (bpm)']);if(r.Scenario){p.fqProphylaxis=bool(r['Quinolone prophylaxis']);p.mrsa=bool(r['MRSA colonisation']);p.oralIntake=bool(r['Able to take oral']);p.resistance=r['Known ESBL / AmpC organism']==='Yes'?'ESBL':r['Known ESBL / AmpC organism']==='No'?'None':'Unknown';p.allergy=r['Penicillin allergy']==='None'?'None':r['Penicillin allergy']==='Severe (anaphylaxis)'?'Immediate':'Unknown';p.allergyDrug=r['Penicillin allergy']==='None'?'None':'Penicillin';}return p;}
function baseline(r,pid,version){const fields=[['ANC','ANC (×10⁹/L)','×10⁹/L'],['CrCl','CrCl (mL/min)','mL/min'],['temperature','Temp (°C)','°C'],['systolicBP','Systolic BP (mmHg)','mmHg'],['heartRate','Heart rate (bpm)','bpm']];return fields.filter(([,key])=>number(r[key])!==null).map(([code,key,unit])=>({eventId:'workbook:'+version+':'+pid+':'+code,patientId:pid,accession:'WB-BASELINE-'+pid+'-'+code,code,value:r[key],unit,observedAt:null,issuedAt:null,status:'final',source:'Uploaded workbook baseline · measurement time not supplied',measurementTimeUnknown:true,_workbookBaseline:true}));}
const api={normalized,mascc,assessment,prefill,baseline};root.FNWorkbookCore=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
